import sys

def min_operations(v):
    if v == 0:
        return 0
    steps = 0
    while v != 0:
        if v % 2 == 0:
            v //= 2
        else:
            v = (v + 1) % 32768
        steps += 1
    return steps

n = int(sys.stdin.readline())
a = list(map(int, sys.stdin.readline().split()))
result = [min_operations(ai) for ai in a]
print(" ".join(map(str, result)))
